<?php
declare(strict_types=1);
require __DIR__.'/../../php/bootstrap.php';require __DIR__.'/LegacyShipmentRepair.php';
use Omnigo\{Database,DeliveryCipher,DeliverySchema,ShipmentSchema,RecentOrderSchema,ShipmentRepository,DeliveryRepository,ShipmentRevision};
function check(bool $v,string $m):void{if(!$v)throw new RuntimeException($m);}
$db=new Database(['dsn'=>'sqlite::memory:']);$db->pdo->exec(file_get_contents(__DIR__.'/../../php/tests/schema.sqlite.sql'));DeliverySchema::install($db);ShipmentSchema::install($db);RecentOrderSchema::install($db);$db->run("INSERT INTO companies VALUES(1,'Örnek'),(2,'Diğer')");
$cipher=DeliveryCipher::withKey(str_repeat('r',32));$date='2026-07-07T20:04:30+03:00';
$base=['orderedAt'=>$date,'customerName'=>'Örnek Alıcı','recipientName'=>'Örnek Alıcı','phone'=>'05000000000','deliveryAddress'=>'Örnek adres','province'=>'Ankara','district'=>'Çankaya','productName'=>'Örnek Ürün','quantity'=>1,'invoiceCents'=>30000,'invoiceName'=>'Örnek Alıcı','invoiceAddress'=>'Fatura adresi','recipientEmail'=>'example@example.invalid','customerType'=>'Bireysel','packageStatus'=>''];
$insert=function(int $company,string $provider,array $payload,?string $key=null)use($db,$cipher,$date){$db->run('INSERT INTO shipment_entries(company_id,city,provider,month,payload,ordered_at,created,updated,source_key) VALUES(?,?,?,?,?,?,?,?,?)',[$company,'Ankara',$provider,'2026-07','','2026-07-07T17:04:30Z',$date,$date,$key]);$id=$db->insertId();$db->run('UPDATE shipment_entries SET payload=? WHERE id=?',[$cipher->seal($company,'shipment:'.$id,$payload),$id]);return $db->one('SELECT * FROM shipment_entries WHERE id=?',[$id]);};
$old=$insert(1,'n11',$base);$auto=$insert(1,'n11',$base,'source-existing');$blank=$insert(1,'Pazarama',[...$base,'productName'=>'','documents'=>['invoice'=>['file'=>'keep.jpg']]]);$other=$insert(2,'n11',$base);$plan=['duplicates'=>[['before'=>$old,'survivorId'=>$auto['id'],'sourceKey'=>'source-existing','orderNumber'=>'O1']],'products'=>[['before'=>$blank,'title'=>'Doğrulanan ürün','sourceKey'=>'pazarama-line','cancellation'=>['quantity'=>1,'cancelledQuantity'=>1],'shipping'=>'','orderNumber'=>'P1','lineId'=>'L1']],'missing'=>[['provider'=>'n11','payload'=>[...$base,'marketplaceShipping'=>'delivered'],'sourceKey'=>'missing-line','orderNumber'=>'O2','lineId'=>'L2']],'deliveries'=>[['provider'=>'n11','externalId'=>'O2:L2','orderNumber'=>'O2','createdAt'=>$date,'buyerName'=>'Örnek Alıcı','phone'=>'05000000000','address'=>'Örnek adres','city'=>'Ankara','district'=>'Çankaya','status'=>'Teslim edildi','active'=>false,'products'=>[],'details'=>['products'=>[['lineId'=>'L2','title'=>'Örnek Ürün','quantity'=>1]]]]]];
$repair=new LegacyShipmentRepair($db,$cipher);$fingerprint=fn()=>hash('sha256',json_encode([$db->all('SELECT * FROM shipment_entries'),$db->all('SELECT * FROM delivery_orders'),$db->all('SELECT * FROM audit')]));$before=$fingerprint();
$bad=$plan;$bad['products'][0]['before']['version']=99;try{$repair->apply(1,'bad-stale',$bad);throw new RuntimeException('Eski sürüm kabul edildi');}catch(RuntimeException $e){check(str_contains($e->getMessage(),'değişti'),'Eski sürüm engeli');}check($before===$fingerprint(),'Eski sürümde bütün işlem geri alındı');
$bad=$plan;$bad['missing'][0]['payload']['marketplaceShipping']='shipped';try{$repair->apply(1,'bad-late',$bad);throw new RuntimeException('Yanlış teslimat kabul edildi');}catch(RuntimeException $e){check(str_contains($e->getMessage(),'doğrulanamadı'),'Geç hata engeli');}check($before===$fingerprint(),'Yazma sonrasındaki hata da bütün işlemi geri aldı');
$bad=$plan;$bad['duplicates'][0]['before']=$other;try{$repair->apply(1,'bad-tenant',$bad);throw new RuntimeException('Başka şirket kabul edildi');}catch(RuntimeException $e){check(str_contains($e->getMessage(),'değişti'),'Şirket sınırı');}check($before===$fingerprint(),'Başka şirket değişmedi');
$revision=ShipmentRevision::read($db,1);$r=$repair->apply(1,'approved-test',$plan);check(count($r['removed'])===1&&count($r['filled'])===1&&count($r['added'])===1,'Beklenen kayıt sayıları');$after=$fingerprint();$again=$repair->apply(1,'approved-test',$plan);check($again['alreadyApplied']&&$after===$fingerprint(),'Tekrar çalışma kayıt veya olay üretmedi');
check($revision!==ShipmentRevision::read($db,1),'İki panelin yenileme sürümü ilerledi');$stored=$db->one('SELECT * FROM shipment_entries WHERE id=?',[$old['id']]);check($stored['removed_at']!==null&&$stored['payload']===$old['payload'],'Mükerrer içerik geri alınabilir biçimde korundu');check($auto===$db->one('SELECT * FROM shipment_entries WHERE id=?',[$auto['id']]),'Otomatik kaynak satır aynen korundu');
$filled=$db->one('SELECT * FROM shipment_entries WHERE id=?',[$blank['id']]);$p=$cipher->open(1,'shipment:'.$blank['id'],$filled['payload']);check($p['invoiceCents']===30000&&$p['documents']['invoice']['file']==='keep.jpg'&&$filled['row_status']==='cancelled','Tutar ve evrak korundu, kesin iptal yansıdı');
$repo=new ShipmentRepository($db,$cipher);$delivery=new DeliveryRepository($db,$cipher);check($repo->listing(1,['all','n11','2026-07'])['total']===2,'Aktif sevkiyat sayısı doğru');foreach([false,true]as $customer)check($delivery->listing(1,'all','n11','delivered',0,20,$customer)['queues']['delivered']===1,'İki rol teslim edilen listesinde aynı kayıt');check($delivery->listing(1,'all','n11','pending',0,20)['items']===[],'Geçmiş teslimat aktif evrak listesine düşmedi');check($delivery->listing(2,'all','n11','delivered',0,20,true)['items']===[],'Müşteri ayrımı korundu');
echo "Geri alma, eski sürüm, şirket ayrımı, tekrar güvenliği, tutar/evrak koruması, teslim edilen kuyruğu ve ortak yenileme kontrolleri geçti.\n";
